import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.DXRWYp4X.js";const u=JSON.parse('{"title":"19 · 深度分级框架：D1–D5","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://R2h1.github.io/fullstack-learning-site/19-深度分级框架"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"19 · 深度分级框架：D1–D5 | 全栈 × AI 学习路径"}],["meta",{"property":"og:description","content":"面试级 · 生产级 · 企业级的全栈 + AI 学习课程（个人笔记，内容优先）"}],["meta",{"property":"og:url","content":"https://R2h1.github.io/fullstack-learning-site/19-深度分级框架"}],["meta",{"name":"twitter:card","content":"summary"}]]},"headers":[],"relativePath":"19-深度分级框架.md","filePath":"19-深度分级框架.md","lastUpdated":1793501444000}'),o={name:"19-深度分级框架.md"};function l(n,t,i,h,s,D){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="_19-·-深度分级框架-d1–d5" tabindex="-1">19 · 深度分级框架：D1–D5 <a class="header-anchor" href="#_19-·-深度分级框架-d1–d5" aria-label="Permalink to &quot;19 · 深度分级框架：D1–D5&quot;">​</a></h1><blockquote><p>达标目标：<strong>能用 D1–D5 给自己任何一项技术能力定坐标，并说出下一级要交付什么。</strong> 一句话理由：「学完了」不是状态，「造出来了」才是。分级从「会讲」升级为「造得出、改得动」，是为了回答一个更硬的问题——离地表最强还差哪几件东西。 衔接：20 章（计划、里程碑与验收物）；15/16 章（AI 应用层的既有内容）；11/13 章（后端与系统设计的既有内容）。</p></blockquote><hr><h2 id="_1-l-与-d-两张梯子各管一件事" tabindex="-1">1. L 与 D：两张梯子各管一件事 <a class="header-anchor" href="#_1-l-与-d-两张梯子各管一件事" aria-label="Permalink to &quot;1. L 与 D：两张梯子各管一件事&quot;">​</a></h2><p>原来的 L1/L2/L3 继续有效，但它只回答「<strong>讲到什么程度</strong>」。新加一把纵向的 D 梯，回答「<strong>长到哪个楼层</strong>」。会讲八股（L2）和造得出引擎（D4）是两回事，很多人误把 L3 当终点。</p><table tabindex="0"><thead><tr><th>级别</th><th>问题</th><th>判据</th></tr></thead><tbody><tr><td>L1 会用</td><td>会不会用</td><td>照教程做出 demo</td></tr><tr><td>L2 面试级</td><td>会不会讲</td><td>不看资料答出「必会」/速答表</td></tr><tr><td>L3 生产级</td><td>有没有做过</td><td>真实项目里做对过工程决策</td></tr><tr><td>D1 地基</td><td>知识地图</td><td>知道这层有什么、坑在哪</td></tr><tr><td>D2 讲得清</td><td>原理叙述</td><td>八股与高频题（= L2）</td></tr><tr><td>D3 生产级</td><td>工程决策</td><td>做过 + 有数字（= L3）</td></tr><tr><td><strong>D4 造得出</strong></td><td>引擎复现</td><td>从零造出该领域核心机制，<strong>带正确性测试</strong></td></tr><tr><td><strong>D5 改得动</strong></td><td>开源与影响</td><td>读得懂主流源码、PR 被 merge、有被转发的深度输出</td></tr></tbody></table><p>「地表最强」的可操作定义：<strong>一个 D3 宽环 + 至少两把 D4 长矛 + 一条证据链收口到 D5</strong>。</p><h2 id="_2-d-梯判据细则-自评用-别自欺" tabindex="-1">2. D 梯判据细则（自评用，别自欺） <a class="header-anchor" href="#_2-d-梯判据细则-自评用-别自欺" aria-label="Permalink to &quot;2. D 梯判据细则（自评用，别自欺）&quot;">​</a></h2><h3 id="d2-讲得清" tabindex="-1">D2 讲得清 <a class="header-anchor" href="#d2-讲得清" aria-label="Permalink to &quot;D2 讲得清&quot;">​</a></h3><ul><li>能白板画出该领域的全链路并讲取舍，接受三层追问不卡壳</li><li>现状：01–18 章的目标层，绝大多数人停在这里</li></ul><h3 id="d3-生产级" tabindex="-1">D3 生产级 <a class="header-anchor" href="#d3-生产级" aria-label="Permalink to &quot;D3 生产级&quot;">​</a></h3><ul><li>真实项目做过工程决策，能给出 QPS、P99、成本、故障 MTTR 中的至少三个数字</li><li>复盘过一次线上故障：现象 → 定位 → 修复 → 防复发</li><li>现状：路线图阶段一/二的验收层；18 章里只有模板，没有载体</li></ul><h3 id="d4-造得出" tabindex="-1">D4 造得出 <a class="header-anchor" href="#d4-造得出" aria-label="Permalink to &quot;D4 造得出&quot;">​</a></h3><ul><li>该领域的<strong>核心引擎</strong>自己实现过一遍，配正确性测试，不是库 API 的调用组合</li><li>例：mini-vLLM 调度器、Raft 集群、LSM 存储引擎、带评估挂 CI 的 RAG 管道</li><li>与 D3 的区别：D3 是「用过并调好」，D4 是「造过并测对」</li></ul><h3 id="d5-改得动" tabindex="-1">D5 改得动 <a class="header-anchor" href="#d5-改得动" aria-label="Permalink to &quot;D5 改得动&quot;">​</a></h3><ul><li>给主流开源项目（LangGraph / vLLM / Eino 之类）提过被 merge 的 PR</li><li>写过至少一篇让同行转发的深度复现或评测</li><li>与 D4 的区别：D4 证明你能造，D5 证明<strong>别人拿你的东西当参考</strong></li></ul><h2 id="_3-站点三层结构" tabindex="-1">3. 站点三层结构 <a class="header-anchor" href="#_3-站点三层结构" aria-label="Permalink to &quot;3. 站点三层结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>定位</th><th>维护规则</th></tr></thead><tbody><tr><td><strong>教材环</strong></td><td>01–18 章</td><td>通用企业级教材，D1–D3</td><td>守既有写作约定，保持通用定位</td></tr><tr><td><strong>长矛区</strong></td><td>19 章起</td><td>操练册：任务、验收物、产出物</td><td>可按阶段迭代，不受教材标准约束</td></tr><tr><td><strong>证据链</strong></td><td>项目仓库、评估报告、输出物</td><td>简历与面试的弹药库</td><td>每阶段收口一次，产出物计数为准</td></tr></tbody></table><p>教材环每章末尾新增 <strong>「深潜入口」D4 框</strong>：一句话指认该领域造一遍核心是什么、对应长矛区哪条路。先补 15 章（AI → 20 章）和 11 章（存储 → 21 章）。</p><h2 id="_4-为什么不能平均用力" tabindex="-1">4. 为什么不能平均用力 <a class="header-anchor" href="#_4-为什么不能平均用力" aria-label="Permalink to &quot;4. 为什么不能平均用力&quot;">​</a></h2><p>广度和深度都想要的人，最常见的下场是「什么都懂一点」——那是平庸的最高配置。强者的形状是 π 型：</p><ul><li><strong>宽环</strong>：处处到 D3，保证接得住任何方向的问题</li><li><strong>长矛</strong>：2–3 个领域捅到 D4，保证追问第五层还有东西可讲</li><li><strong>证据链</strong>：把前两者变成别人否认不了的东西（仓库、报告、PR、文章）</li></ul><p>长矛必须早选，因为引擎级能力靠累计小时堆，晚选一个月就少一个月。默认两把：<strong>AI 推理层</strong>（20 章）与<strong>分布式内核</strong>（21 章），二者互喂——RAG 系统本身就是分布式系统。</p><h2 id="_5-深水区词汇表-扫盲用-混个脸熟" tabindex="-1">5. 深水区词汇表（扫盲用，混个脸熟） <a class="header-anchor" href="#_5-深水区词汇表-扫盲用-混个脸熟" aria-label="Permalink to &quot;5. 深水区词汇表（扫盲用，混个脸熟）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话</th></tr></thead><tbody><tr><td>KV Cache</td><td>缓存注意力 K/V，用显存换计算，推理成本大头</td></tr><tr><td>Prefill / Decode</td><td>算力密集 / 带宽密集，TTFT 与 TPOT 分别对应</td></tr><tr><td>Continuous Batching</td><td>请求动态进出 batch，vLLM 吞吐来源</td></tr><tr><td>LoRA / QLoRA</td><td>低秩旁路微调 / 量化基座 + LoRA，单卡可行</td></tr><tr><td>AWQ / GPTQ / FP8</td><td>主流权重量化格式</td></tr><tr><td>RAGAS / Faithfulness</td><td>检索增强评估框架 / 「回答是否只基于检索内容」</td></tr><tr><td>LLM-as-Judge</td><td>用模型当裁判打分，注意偏差与校准</td></tr><tr><td>MRR / Recall@k</td><td>排序与召回质量指标</td></tr><tr><td>Raft</td><td>共识协议，选主 + 日志复制</td></tr><tr><td>LSM-tree</td><td>写优化存储结构（RocksDB），对位 B+ 树（InnoDB）</td></tr><tr><td>TTFT / TPOT</td><td>首 token 延迟 / 每输出 token 时间</td></tr></tbody></table><h2 id="_6-面试高频题速答" tabindex="-1">6. 面试高频题速答 <a class="header-anchor" href="#_6-面试高频题速答" aria-label="Permalink to &quot;6. 面试高频题速答&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题</th><th>速答要点</th></tr></thead><tbody><tr><td>你怎么定义自己的技术深度</td><td>用 D 梯报坐标：哪个领域到 D4、验收物是什么</td></tr><tr><td>八股和项目哪个重要</td><td>八股到 D2 是门票，定级看 D3 数字与 D4 作品</td></tr><tr><td>怎么快速评估一个新领域</td><td>画 D 梯 → 找该领域「造一遍核心」的最小路径</td></tr></tbody></table><h2 id="_7-达标标准" tabindex="-1">7. 达标标准 <a class="header-anchor" href="#_7-达标标准" aria-label="Permalink to &quot;7. 达标标准&quot;">​</a></h2><p><strong>D2：</strong></p><ul><li>[ ] 向别人讲清 L 与 D 的分工，报出自己每项能力的 D 坐标</li></ul><p><strong>D3：</strong></p><ul><li>[ ] 给自己两个最熟领域写出「下一级验收物」的具体定义</li></ul><p><strong>D4：</strong></p><ul><li>[ ] 长矛区任意一章完成其验收物（带测试 + 带报告）</li></ul>',34)])])}const g=d(o,[["render",l]]);export{u as __pageData,g as default};
